# -*- coding: utf-8 -*-
B=[
dict(a=1,z=3,star=3,
lit='「耶和華的話臨到耶利米說：你們要聽這約的話，告訴猶大人和耶路撒冷的居民，對他們說：耶和華以色列的神這樣說：不聽從這約之話的人，必受咒詛。」',
key=[('耶利米','H3414','yirmeyahu','耶和華高舉'),('居民','H3427','yoshevei','居住的人'),('神','H430','elohei','神'),('咒詛','H779','arur','受咒詛的'),('猶大','H3063','yehudah','猶大')],
gram=['**{H779}**（arur，受咒詛的）：這個字帶出申命記二十七、二十八章的「祝福與咒詛」。**這約**，指的是西奈山與摩押平原所立的約，不是新的約。','整段的核心動詞是「聽」，這是希伯來文 **שָׁמַע**（shama），既是「聽見」，也是「聽從」。這一章把這個字寫了八次以上，是這一章的鑰字。'],
exp=['這一章以**約**開場：耶和華的話臨到耶利米，叫他去告訴猶大人和耶路撒冷的居民：要聽這約的話。這裡的「約」，指的是神與以色列在西奈山、摩押平原所立的約，申命記有完整的記載。','三節有一句很重的話：不聽從這約之話的人，必受咒詛。這不是一句新的威脅，而是**約本來就有的結構**：聽從，有祝福；不聽，有咒詛。（申二十七章二十六節）','值得留意的是「聽」字。希伯來文的「聽」，不只是耳朵聽見，而是**聽見就去做**。一個聽見卻不做的人，在希伯來文裡，並沒有真正「聽」過。']),
dict(a=4,z=5,star=2,
lit='「這約是我將你們的列祖從埃及地、從鐵爐中領出來的那日所吩咐他們的：你們要聽從我的聲音，照我一切所吩咐你們的去行，這樣你們就作我的子民，我也作你們的神，好堅立我向你們列祖所起的誓，賜給他們流奶與蜜之地，正如今日一樣。我回答說：耶和華啊，阿們！」',
key=[('鐵爐','H3564','kur ha-barzel','煉鐵的爐；埃及的苦工'),('鐵','H1270','barzel','鐵'),('起誓','H7621','ha-shevu\'ah','誓言'),('流','H2100','zavat','流出'),('奶','H2461','chalav','奶'),('蜜','H1706','dvash','蜜'),('阿們','H543','amen','誠然、確實')],
gram=['**{H3564}**（鐵爐）：這個詞在申四章二十節、王上八章五十一節也出現，是埃及為奴的象徵。神把以色列從鐵爐中領出來，作為約的開端。','**{H543}**（amen，阿們）：先知聽見這話，立刻說「阿們」。這是一個立約者的回應：我同意，我承擔。**{H7621}** 是神向列祖起的誓，**約是從恩典開始的**。'],
exp=['四節把「約」的來歷說得很清楚：這約，是**從鐵爐中領出來的那日**所立的。順序很重要：先是拯救，然後是約。神沒有說「你們先守約，我才救你們」，而是「我先救了你們，現在請你們聽我的聲音」。','約的內容只有一句話：你們作我的子民，我也作你們的神。這是**整本聖經最簡單的一句話**，也是我們今天所有關係的核心：我屬於祂，祂屬於我。','先知的回答很短：「耶和華啊，阿們！」這個回答值得注意：他不是在討論，也不是在辯論，他是**一個同意這約的人**。接下來，他要為這個約付上很大的代價。']),
dict(a=6,z=8,star=2,
lit='「耶和華對我說：你要在猶大的城邑中和耶路撒冷的街上宣告這一切話：你們要聽這約的話，並且遵行。因為我將你們的列祖從埃及地領出來的那日，直到今日，都是從早起來，切切地警告他們說：你們要聽從我的聲音。他們卻不聽從，也不側耳而聽，各人隨從自己頑梗的惡心去行。所以我使這約中一切咒詛的話臨到他們身上，這約是我吩咐他們行的，他們卻不去行。」',
key=[('宣告','H7121','qra','呼喊、宣告'),('早起','H7925','hashkem','早早起來；原文是「早起」的動詞形式'),('側','H5186','hitu','側、傾斜'),('耳','H241','oznam','耳朵'),('頑梗','H8307','bishrirut','固執'),('心','H3820','libam','心')],
gram=['**{H7925}**（早起）：這是耶利米書的一個特色用語（七章十三節、二十五節；二十五章三至四節），形容神像一位早起的父親，一次又一次地去叫醒孩子。','**{H5186}**（側）與 **{H241}**（耳）：「不側耳而聽」就是不願意把耳朵傾向神；**{H8307}**（頑梗）是說心的固執。這三個字合起來，是一個人不聽的三個步驟。'],
exp=['六節是一個**公開的命令**：要在城邑中、街市上宣告。這不是一個私下的勸告，而是在公共場所的宣告。聖經的約從來不是私人的事。','七節是一個很感人的畫面：神**從早起來**，切切地警告。「早起」是形容一個很在乎的人，這位父親天還沒亮就起來，去叫孩子起床。這就是神對百姓的態度：不是遠遠地等著審判，而是一次又一次地呼喚。','八節是結局：他們卻不聽從，不側耳而聽。三個動作：不聽，不側耳，隨從自己的惡心。**頑梗，是從耳朵開始的。**一個人若不願意傾聽，就會用自己的心代替神的話，而這顆心，是頑梗的。']),
dict(a=9,z=10,star=3,
lit='「耶和華對我說：在猶大人和耶路撒冷的居民中，發現有同謀背叛的事。他們轉去犯他們先祖的罪孽，那些先祖不肯聽我的話，隨從別神，事奉它們。以色列家和猶大家都違背了我與他們列祖所立的約。」',
key=[('同謀','H7195','qesher','同盟、密謀'),('罪孽','H5771','avonot','罪孽、偏離'),('先','H7223','ha-rishonim','最先的'),('不肯','H3985','me\'anu','拒絕'),('違背','H6565','heferu','破壞、廢棄'),('立約','H3772','karati','立約（直譯：砍）')],
gram=['**{H7195}**（qesher，同謀）：這個字用在「叛變」，如王下十一章十四節的「謀反」。這裡是說，背棄約已經不是個別人的軟弱，而是一場**集體的密謀**。','**{H3772}**（立約，直譯是「砍」）：古代立約，要殺牲畜、從中間分開，雙方從中走過（創十五章）。**{H6565}**（破壞）就是把約「撕開」。這裡有一個很重的意思：神為立約付了代價，人卻輕易撕毀。'],
exp=['九節有一個令人驚訝的詞：**同謀**。神說，在猶大人與耶路撒冷居民中，發現有同謀背叛的事。這不是「幾個人犯錯」，而是一個**集體的默契**：大家都這樣，所以沒有人覺得有問題。','十節揭示了這個同謀的歷史：他們轉去犯先祖的罪孽，那些先祖不肯聽神的話。這是一條**代代相傳的路**：一個不肯聽的父親，教出一個不肯聽的兒子。今天我們每一個人，也在向下一代傳遞某一種「聽」或「不聽」。','最後一句很重：以色列家和猶大家都背了約。十個支派與兩個支派，南北兩國，全都在裡面。**沒有一個人，可以說「我是例外」。**']),
dict(a=11,z=13,star=2,
lit='「所以耶和華這樣說：看哪，我必使災禍臨到他們，是他們不能逃脫的；他們必向我呼求，我卻不聽。那時猶大城邑的人和耶路撒冷的居民，要去向他們燒香所供奉的神呼求，只是遭難的時候，這些神絕不拯救他們。猶大啊，你神的數目與你城的數目一樣多；你為那可恥的巴力築的燒香的壇，也與耶路撒冷街道的數目一樣多。」',
key=[('逃脫','H3201','yukhlu la-tset','能夠出去'),('可恥','H1322','la-boshet','羞恥；巴力的別名'),('巴力','H1168','la-ba\'al','巴力（主、丈夫）'),('街道','H2351','chutsot','街道、外面')],
gram=['**{H1322}**（boshet，羞恥）：以色列人常把「巴力」的名字，改讀為「羞恥」（參士六章三十二節的耶路巴力→耶路比設）。這裡的「那可恥的」是一個故意的諷刺。','十一至十二節的「呼求」（**זָעַק**）與「拯救」（**יָשַׁע**）各出現兩次：一邊是人向神呼求、神不聽，一邊是人向別神呼求、別神不救。這是整段的對稱：**呼求的對象錯了。**'],
exp=['十一節是一個很重的反轉：他們必向我呼求，我卻不聽。這和十二節的畫面一起看，非常諷刺：災禍臨到，他們去向自己供奉的神呼求，可是那些神絕不拯救。**你一直供奉的，在你最需要的時候，沒有一個來。**','十三節是一個極具畫面的數字：猶大啊，你神的數目，與你城的數目一樣多；你的壇，與耶路撒冷街道的數目一樣多。街街都有壇，城城都有神。這是一個很誇張的圖像，說的是一個民族已經**不知道哪一位才是真的神**。','這裡有一個很深的問題：我遇到災難的時候，第一個想到的是誰？**在最危急的時候我第一個去呼求的，才是我真正的神。**這是一個很準確的測驗，不是為了定我們的罪，而是為了讓我們誠實。']),
dict(a=14,z=17,star=3,
lit='「所以你不要為這百姓禱告，不要為他們呼求禱告；因為他們遭難向我呼求的時候，我必不聽。我所親愛的，既行許多淫亂，神聖的祭肉也離開了你，你在我殿中做什麼呢？你作惡就歡喜。耶和華從前稱你的名為青橄欖樹，華美，果子結得好；現在祂用大轟動的聲音，點火在其上，枝子也被折斷了。栽培你的萬軍之耶和華已經說了要降禍攻擊你，因為以色列家和猶大家行惡，向巴力燒香，惹我發怒。」',
key=[('禱告','H6419','titpallel','代求、禱告'),('呼求','H7440','rinnah','呼喊'),('我所親愛的','H3039','yedidi','我的所愛'),('青橄欖樹','H2132','zayit ra\'anan','青翠的橄欖樹'),('轟動','H1999','hamullah','喧嚷的聲音'),('火','H784','esh','火'),('惹我發怒','H3707','leha\'iseni','使我發怒')],
gram=['**{H6419}**（titpallel，禱告）：這是「代求」的字根，第二次出現在七章十六節，十四章十一節，十五章一節還會再出現，成為一個四次的禁令。**這是一個特別的情況，不是普遍的規則。**','**{H3039}**（yedidi，我所親愛的）：與「詩篇一百二十七篇二節」的「蒙愛的」同字根，這是一個溫柔的稱呼；神用它稱呼猶大，同時控訴她。**{H2132}** 青橄欖樹，是一個繁茂而有生機的樹，用火燒，是用大轟動的聲音。'],
exp=['十四節是整章最令人震驚的一句：**不要為這百姓禱告。**這是耶利米書的第二次（七章十六節），之後還有兩次（十四章十一節，十五章一節）。這不是普遍的原則，也不是說我們不要為人代求；新約仍然教導我們為人代求，連仇敵也包括在內。這是在**一個特定的歷史時刻**，神對耶利米的特別命令：審判已定，代求的門暫時關上了。','十五節有一個溫柔的稱呼：「我所親愛的」。神仍然稱呼猶大為「我所親愛的」，同時控訴她行許多淫亂。這是一位被背叛的愛人，**心裡仍然有愛，口中卻說出審判。**','十六節是一幅最美、也最令人心碎的圖畫：從前神稱你的名為青橄欖樹，華美，果子結得好；現在祂用大轟動的聲音，點火在其上。同一棵樹，從茂盛到焚燒。神是栽培者（十七節），也是審判者；**祂栽培過的，也有權收回。**但這不是結局，因為後面還有新約（三十一章）。']),
dict(a=18,z=20,star=3,
lit='「耶和華指示我，我就知道；那時你讓我看見他們的行為。我卻像一隻溫馴的羊羔被牽去宰殺；我不知道他們同謀害我，說：讓我們把樹連同它的果子一起毀滅，把他從活人之地剪除，使他的名不再被人記念。按公義審判、察驗肺腑心腸的萬軍之耶和華啊，求你讓我看見你向他們報仇，因為我已經把我的案件向你陳明了。」',
key=[('羊羔','H3532','kevesh','羊羔'),('溫馴','H441','alluf','溫馴的；也有「牛犢」之意'),('宰殺','H2873','litbo\'ach','屠宰'),('肺腑','H3629','kelayot','腎臟（心思的所在）'),('察驗','H974','bochen','試驗、察驗'),('報仇','H5360','niqmatkha','伸冤、報應'),('陳明','H1540','gillitti','揭開、呈現')],
gram=['**{H3629}**（kelayot，腎）：在希伯來思想裡，「腎」是人最隱密的情感與良心所在（詩七篇九節、十六篇七節）。「察驗肺腑心腸」是說：神看透人最深處的動機。','**{H1540}**（gillitti，陳明、揭開）：先知把案件「攤開」在神面前，這個動詞也用於啟示。**{H3532}**（羊羔）的畫面，後來在賽五十三章七節出現：「像羊羔被牽到宰殺之地」，新約把這個形象連結到耶穌。'],
exp=['十八節是一個轉折：先知說，是耶和華指示我，我才知道。**他本來不知道。**十九節補了一句很令人心疼的話：我卻像一隻溫馴的羊羔被牽去宰殺；我不知道他們同謀害我。他是一個天真的人，直到被人暗算，才發現身邊有人要他的命。','他們說的話很有條理：讓我們把樹連同果子毀滅，把他從活人之地剪除，使他的名不再被記念。他們要的，不只是他的命，還有他的**名字**。在古代，被人忘記，比死更可怕。','二十節是先知的禱告：按公義審判、察驗肺腑心腸的神啊，我把我的案件向你陳明了。這是一個很值得學習的禱告：先知沒有自己報仇，而是**把案件交給神**。他說：求你讓我看見你報仇。這是詩篇式的呼求，要小心讀；新約教導我們愛仇敵，但也教導我們把審判交給神（羅十二章十九節）。']),
dict(a=21,z=23,star=3,
lit='「所以，耶和華論到亞拿突人這樣說——他們尋索你的命，說：你不要奉耶和華的名說預言，免得你死在我們手中——所以萬軍之耶和華這樣說：看哪，我必刑罰他們；他們的年輕人必死在刀下，他們的兒女必因饑荒而死；他們必沒有餘剩的人，因為在追討之年，我必使災禍臨到亞拿突人。」',
key=[('尋索','H1245','mevaqshim','尋找、謀求'),('性命','H5315','nafshekha','性命、你的生命'),('說預言','H5012','tinnave','說預言'),('年輕人','H970','ha-bachurim','青年人'),('刀','H2719','ba-cherev','刀劍'),('饑荒','H7458','ba-ra\'av','饑荒'),('餘剩','H7611','she\'erit','餘剩的人')],
gram=['**{H1245}**（baqash，尋索）：「尋索你命的人」是詩篇常見的說法（詩三十五篇四節）。這裡很特別：想要殺他的，竟然是他的**家鄉人**（亞拿突是耶利米的故鄉）。','**{H7611}**（she\'erit，餘剩）：「沒有餘剩的人」，是這一段審判最重的一句。「餘剩」在耶利米書是一個希望的字（二十三章三節），這裡卻被剝奪。'],
exp=['二十一節揭開了先知的痛處：想要殺他的人，是亞拿突人，也就是**他的家鄉人**（耶一章一節）。他們對他說：你不要奉耶和華的名說預言，免得你死在我們手中。最傷人的，往往不是敵人，而是熟悉的人。','這句話很值得我們停下來想：一個先知，因為說了神的話，被自己的家鄉人威脅。耶穌在拿撒勒也有同樣的經歷：先知在本地，是沒有人尊敬的（路四章二十四節）。**說真話的人，常常要付上孤單的代價。**','二十二、二十三節是神對這些人的判決：年輕人死在刀下，兒女死於饑荒，沒有餘剩的人。這是一個很重的審判，我們不能輕輕帶過；它提醒我們：威脅神所差遣的人，不是小事。可是請留意，這裡只是針對**亞拿突這些謀害先知的人**，不是對一般人的普遍規則。']),
]
